        "oklch(0.769 0.188 70.08)",
        "oklch(0.627 0.265 303.9)",
        "oklch(0.645 0.246 16.439)",
      ],
    },
  },
  elevation: {
    light: {
      sm: "0 1px 2px oklch(0 0 0 / 0.05)",
