  feedback: {
    hover: {
      fill: "accent",
      surface: {
        shadow: "sm",
        light: {
          background: "accent",
          border: "transparent",
          borderTop: "transparent",
          borderBottom: "transparent",
        },
        dark: {
          background: "accent",
          border: "transparent",
          borderTop: "transparent",
          borderBottom: "transparent",
        },
      },
    },
    press: {
      scale: 1,
      surface: {
        shadow: null,
        light: { background: "border", border: "transparent" },
