      focus: { color: "ring" },
    },
    choice: {
      corner: 4,
      shade: "none",
      radioChecked: { face: "none" },
      mark: 8,
    },
    switch: {
      track: { pointer: [32, 18], touch: [44, 24] },
      trackOffFace: { light: "input", dark: "oklch(0.28969 0 0)" },
