        gradient: null,
        border: "transparent",
        checkedBackground: { light: "background", dark: "primary-foreground" },
        checkedBorder: "transparent",
      },
    },
    slider: {
      face: "muted",
      shade: "none",
      edge: { color: "none", width: 0 },
      knob: {
        size: { pointer: 16, touch: 20 },
        pressed: { pointer: 16, touch: 32 },
        background: { light: "background", dark: "foreground" },
        gradient: null,
        border: "primary",
      },
    },
    popup: { corner: "control" },
    list: { item: { highlight: "accent", edge: "none" } },
    tabs: { track: { face: "muted", edge: "none", corner: "control" } },
  },
  meta: {
    overview:
      "shadcn/ui's neutral palette paired with flat surfaces (`press.scale: 1`) and Tailwind-style border/shadow lifts (`new-york-v4`).",
    elevationNote:
      "Flat elevation model: cards and floating surfaces sit on neutral background steps with subtle drop shadows and crisp 1px borders.",
    dos: [
      "Keep press interactions flat (`press.scale: 1`); signal hover and press via surface and opacity changes.",
    ],
    donts: [
      "Do not add backdrop blur, specular rim highlights, or press shrink to flat shadcn surfaces.",
    ],
    contrastWaivers: [
      { fg: "muted-foreground", bg: "muted", source: "shadcn neutral muted-foreground on muted" },
      {
        fg: "muted-foreground",
        bg: "surface",
        source: "shadcn neutral muted-foreground on secondary",
      },
    ],
  },
});

export default shadcn;
